<?php
require_once __DIR__.'/bootstrap.php';require_admin();$pageTitle='Màu sắc';$active='colors';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);try{if(($_POST['action']??'')==='delete'){$pdo->prepare("DELETE FROM mausac WHERE id=?")->execute([$id]);flash('success','Đã xóa màu sắc.');}else{$name=trim((string)($_POST['ten_mau']??''));$hex=strtoupper(trim((string)($_POST['ma_hex']??'#C9C2AE')));$status=(int)($_POST['trang_thai']??1);if($name===''||!preg_match('/^#[0-9A-F]{6}$/',$hex))throw new RuntimeException('Tên màu hoặc mã HEX không hợp lệ.');if($id)$pdo->prepare("UPDATE mausac SET ten_mau=?,ma_hex=?,trang_thai=? WHERE id=?")->execute([$name,$hex,$status,$id]);else $pdo->prepare("INSERT INTO mausac (ten_mau,ma_hex,trang_thai) VALUES (?,?,?)")->execute([$name,$hex,$status]);flash('success','Đã lưu màu sắc.');}}catch(Throwable $e){flash('error',$e instanceof PDOException?'Không thể lưu/xóa. Tên màu có thể đã tồn tại hoặc màu đang được biến thể sử dụng.':$e->getMessage());}redirect('colors.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM mausac WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query("SELECT m.*,COUNT(b.id) AS so_bien_the FROM mausac m LEFT JOIN bien_the_sanpham b ON b.mau_sac_id=m.id GROUP BY m.id ORDER BY m.id DESC")->fetchAll();require __DIR__.'/admin-header.php';?>
<div class="form-grid"><section class="panel"><h2><?=$edit?'Sửa màu':'Thêm màu sắc'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="field" style="margin-top:18px"><label>TÊN MÀU *</label><input name="ten_mau" required value="<?=e($edit['ten_mau']??'')?>"></div><div class="field" style="margin-top:15px"><label>MÃ HEX *</label><input name="ma_hex" pattern="#[0-9A-Fa-f]{6}" value="<?=e($edit['ma_hex']??'#C9C2AE')?>" required></div><div class="field" style="margin-top:15px"><label>TRẠNG THÁI</label><select name="trang_thai"><option value="1" <?=((int)($edit['trang_thai']??1)===1)?'selected':''?>>Hoạt động</option><option value="0" <?=((int)($edit['trang_thai']??1)===0)?'selected':''?>>Ẩn</option></select></div><div class="form-actions"><button class="btn">Lưu màu</button><a class="btn light" href="colors.php">Làm mới</a></div></form></section><section class="panel"><h2>Bảng màu La Muse</h2><p class="muted">Chọn mã HEX nhất quán với màu thực tế của sản phẩm. Màu ở đây dùng cho bộ lọc và biến thể, không thay thế ảnh sản phẩm.</p></section></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Màu</th><th>Tên</th><th>HEX</th><th>Biến thể</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="swatch" style="background:<?=e($r['ma_hex'])?>"></span></td><td><?=e($r['ten_mau'])?></td><td><?=e($r['ma_hex'])?></td><td><?=$r['so_bien_the']?></td><td><span class="badge <?=((int)$r['trang_thai']===1)?'':'off'?>"><?=((int)$r['trang_thai']===1)?'Hoạt động':'Ẩn'?></span></td><td><div class="actions"><a class="btn small light" href="?edit=<?=$r['id']?>">Sửa</a><form class="inline" method="post" onsubmit="return confirm('Xóa màu này?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn small danger">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/admin-footer.php';?>
